const conj = a => cx(a.re, -a.im);
const neg = a => cx(-a.re, -a.im);
const YEAR = 365.25 * 86400;

function smibDiagram() {
    return drawing(`<circle cx="70" cy="120" r="30"/>${dt(70, 126, 'G')}<path d="M100 120h40m80 0h40M260 120V70h120m80 0h60v50M260 120v50h120m80 0h60v-50M520 120h50m0 -40v80m5 -80v80M575 120h40"/><rect x="140" y="108" width="80" height="24"/><rect x="380" y="58" width="80" height="24"/><rect x="380" y="158" width="80" height="24"/>${dt(180, 98, "X′d + XT")}${dt(420, 48, 'Line 1')}${dt(420, 210, 'Line 2')}${dot(260, 120)}${dot(520, 120)}<path d="M290 170l14 -12 -6 12 14 -12" stroke="#b5532d"/>${dt(300, 200, 'Fault')}<circle cx="640" cy="120" r="24"/>${dt(640, 126, '∞')}${dt(70, 175, "E′∠δ")}${dt(640, 168, 'V∠0°')}${dt(360, 245, 'Single machine, infinite bus · fault on line 2 at the sending end')}`, 'Generator with transient reactance and transformer feeding two parallel lines to an infinite bus; a fault is marked on line 2 near the sending bus');
}
